#!/bin/sh
# Tests the classi-staging files of Classi v3 (supabase/staging/*v3*.sql, generated by scripts/staging/gen_v3_files.py) on
# throwaway LOCAL databases that look like classi-staging today: every migration up to D-08 step A applied and recorded,
# the staging marker, and the demo data (synthetic). A second base has D-08 step B as well. Never touches a hosted
# database. The files only run on the classi-staging cluster id: the test runs copies in which that one constant is
# replaced by this server's cluster id, and checks that nothing else differs. Every check prints PASS: or FAIL:.
# Usage: sh supabase/tests/staging_v3_test.sh
set -u
T="$(cd "$(dirname "$0")" && pwd)"; REPO="$(cd "$T/../.." && pwd)"
ST="$REPO/supabase/staging"; L=20261120000000_v3_ledger; S=20261120010000_v3_business_access
STAGING_ID=7702070854497379551
P="psql -h ${PGSOCK:-/var/tmp/pgc} -p ${PGPORT:-54329} -U postgres -q"
W=$(mktemp -d); BASE=ct_v3_base; BASEB=ct_v3_baseb; DB=ct_v3
pass=0; fail=0
ok() { echo "PASS: $1"; pass=$((pass + 1)); }
ko() { echo "FAIL: $1"; fail=$((fail + 1)); }
q() { $P -d "$DB" -Atc "$1"; }
fresh() { $P -c "drop database if exists $DB" -c "create database $DB template ${1:-$BASE}" >/dev/null; }
run() { $P -d "$DB" -v ON_ERROR_STOP=1 -f "$1" > "$W/out" 2>&1; }
# the whole public schema (functions with body, settings and grants; tables; columns), the triggers, the recorded migrations
schema() { q "select md5(concat_ws('#',
  (select string_agg(format('%s(%s)|%s|%s|%s|%s|%s', p.proname, pg_get_function_identity_arguments(p.oid), md5(p.prosrc), coalesce(array_to_string(p.proconfig, ','), '-'), p.prosecdef,
     has_function_privilege('anon', p.oid, 'execute'), has_function_privilege('authenticated', p.oid, 'execute')), E'\n' order by p.proname, pg_get_function_identity_arguments(p.oid)) from pg_proc p where p.pronamespace='public'::regnamespace),
  (select string_agg(table_name || '.' || column_name, ',' order by table_name, column_name) from information_schema.columns where table_schema='public'),
  (select string_agg(tgrelid::regclass || '.' || tgname, ',' order by tgrelid::regclass::text, tgname) from pg_trigger where not tgisinternal),
  (select string_agg(version, ',' order by version) from supabase_migrations.schema_migrations),
  (select string_agg(key || '=' || value, ',' order by key) from public.app_settings)))"; }
# the same pieces one by one (printed only when a comparison fails)
parts() { q "select 'fn ' || p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ') ' || md5(p.prosrc) || ' ' || coalesce(array_to_string(p.proconfig, ','), '-') || ' ' || p.prosecdef || ' '
    || has_function_privilege('anon', p.oid, 'execute') || has_function_privilege('authenticated', p.oid, 'execute') from pg_proc p where p.pronamespace='public'::regnamespace
  union all select 'col ' || table_name || '.' || column_name from information_schema.columns where table_schema='public'
  union all select 'trg ' || tgrelid::regclass || '.' || tgname from pg_trigger where not tgisinternal
  union all select 'mig ' || version from supabase_migrations.schema_migrations
  union all select 'set ' || key || '=' || value from public.app_settings order by 1"; }
# row counts of every public table (data)
data() { q "select md5(string_agg(c.relname || '=' || (xpath('/row/n/text()', query_to_xml(format('select count(*) as n from public.%I', c.relname), false, true, '')))[1]::text, ',' order by c.relname))
  from pg_class c where c.relnamespace='public'::regnamespace and c.relkind='r'"; }
expect_refusal() { # <label> <file> <text>: refused, and nothing at all changed
  before="$(schema)$(data)"
  if run "$2"; then ko "$1: it ran"; return; fi
  grep -q "$3" "$W/out" || { ko "$1: not the expected refusal ($(grep -m1 ERROR "$W/out"))"; return; }
  [ "$(schema)$(data)" = "$before" ] && ok "$1 (refused, nothing changed)" || ko "$1: refused but something changed"
}
expect_ok() { if run "$2"; then ok "$1"; else ko "$1: $(grep -m1 ERROR "$W/out")"; fi; }
fingerprints() { $P -d "$DB" -At -F '|' -f "$1" 2>/dev/null | grep -E '^(data|settings|visible)' | sort; }

# ---------- bases like classi-staging today ----------
build() { # <db> <last migration to apply>
  $P -c "drop database if exists $1" -c "create database $1" >/dev/null 2>&1
  D="env PGOPTIONS=-cclient_min_messages=warning $P -d $1 -v ON_ERROR_STOP=1"
  $D -f "$T/supabase_stub.sql" >/dev/null
  $D -c "create schema if not exists supabase_migrations; create table if not exists supabase_migrations.schema_migrations (version text primary key, name text, statements text[])" >/dev/null
  for f in "$REPO"/supabase/migrations/*.sql; do
    v=$(basename "$f" | cut -d_ -f1); [ "$v" \> "$2" ] && break
    $D -f "$f" >/dev/null || { echo "FAIL: base: $f did not apply"; exit 1; }
    $D -c "insert into supabase_migrations.schema_migrations (version, name) values ('$v', '$(basename "$f" .sql | cut -d_ -f2-)')" >/dev/null
  done
  $D -f "$REPO/supabase/seed.sql" >/dev/null
  $D -c "insert into public.app_secrets (key, value) values ('deploy_env', 'staging'), ('dispatch_secret', 'stg-secret'), ('private_photos_app', 'deployed') on conflict (key) do update set value = excluded.value" >/dev/null
  $D -c "insert into storage.buckets (id, name, public) values ('photos-private', 'photos-private', false) on conflict (id) do nothing" >/dev/null
}
build $BASE 20261114000000
build $BASEB 20261114010000
LOCAL_ID=$($P -d $BASE -Atc "select system_identifier from pg_control_system()")

# ---------- the files ----------
(cd "$REPO" && PGSOCK=${PGSOCK:-/var/tmp/pgc} PGPORT=${PGPORT:-54329} python3 scripts/staging/gen_v3_files.py --check > "$W/gen" 2>&1) \
  && ok "the staging files are exactly what the generator makes from the committed migrations" || ko "staging files are stale: $(cat "$W/gen")"
for f in apply_$L apply_$S rollback_$S rollback_${S}_discard_data rollback_$L rollback_${L}_discard_data; do
  [ "$(grep -c "$STAGING_ID" "$ST/$f.sql")" = 1 ] || ko "$f: cluster id count"
  sed "s/$STAGING_ID/$LOCAL_ID/" "$ST/$f.sql" > "$W/$f.sql"
  [ "$(diff "$ST/$f.sql" "$W/$f.sql" | grep -c '^[<>]')" = 2 ] && ok "$f: the test copy differs only in the cluster id line" || ko "$f: test copy differs in more"
done
for f in snapshot_v3 verify_v3; do
  grep -q "$STAGING_ID" "$ST/$f.sql" && ko "$f: should not need the cluster id (read only)" || ok "$f: read only, no cluster-specific line"
  grep -Eiq '^\s*(insert into (public|supabase_migrations)|update |delete from |drop |alter |create (table|function|or replace)|grant |revoke )' "$ST/$f.sql" \
    && ko "$f: contains a write outside its temp table" || ok "$f: no write to the database (only a temp table, then ROLLBACK)"
  [ "$(tail -1 "$ST/$f.sql")" = "rollback;" ] && ok "$f: ends in rollback" || ko "$f: does not end in rollback"
done
for m in $L $S; do
  awk '/^-- ===== BEGIN MIGRATION/{f=1;next}/^-- ===== END MIGRATION/{f=0}f' "$ST/apply_$m.sql" | cmp -s - "$REPO/supabase/migrations/$m.sql" \
    && ok "apply_$m: the embedded migration is the committed file, byte for byte" || ko "apply_$m: embedded migration differs"
  for r in rollback_$m rollback_${m}_discard_data; do
    awk '/^-- ===== BEGIN ROLLBACK/{f=1;next}/^-- ===== END ROLLBACK/{f=0}f' "$ST/$r.sql" > "$W/body"
    grep -v '^--' "$REPO/supabase/rollback/$m.down.sql" | grep -v '^begin;$' | grep -v '^commit;$' | cmp -s - "$W/body" \
      && ok "$r: the embedded rollback is the committed down file" || ko "$r: embedded rollback differs"
  done
done

# ---------- apply the ledger: refusals ----------
fresh; expect_refusal "ledger outside classi-staging (the committed file)" "$ST/apply_$L.sql" "refusing: not the classi-staging database"
fresh; q "delete from public.app_secrets where key='deploy_env'" >/dev/null; expect_refusal "ledger without the staging marker" "$W/apply_$L.sql" "not marked staging"
fresh; q "insert into supabase_migrations.schema_migrations (version) values ('20261120000000')" >/dev/null; expect_refusal "ledger already recorded" "$W/apply_$L.sql" "already recorded"
fresh; q "insert into supabase_migrations.schema_migrations (version) values ('20261115000000')" >/dev/null; expect_refusal "ledger with an unknown newer migration" "$W/apply_$L.sql" "newest recorded migration is not"
fresh; q "delete from supabase_migrations.schema_migrations where version='20261114000000'" >/dev/null; expect_refusal "ledger before D-08 step A" "$W/apply_$L.sql" "newest recorded migration is not"
fresh; q "alter table public.sms_log disable row level security" >/dev/null; expect_refusal "ledger with RLS off on a public table" "$W/apply_$L.sql" "row level security off"
fresh; q "update public.app_settings set value='true' where key='subscriptions_required'" >/dev/null; expect_refusal "ledger with subscriptions_required on" "$W/apply_$L.sql" "subscriptions_required is on"
fresh; q "create or replace function public.owner_has_access(p_teacher uuid, p_institute uuid) returns boolean language sql stable security definer set search_path = public as \$\$ select true \$\$" >/dev/null
expect_refusal "ledger with a changed owner_has_access" "$W/apply_$L.sql" "v3 functions and the three it replaces"
fresh; q "create table public.charges (id int)" >/dev/null; q "alter table public.charges enable row level security" >/dev/null
expect_refusal "ledger with a charges table already there" "$W/apply_$L.sql" "v3 tables"
fresh; expect_refusal "business access before the ledger" "$W/apply_$S.sql" "newest recorded migration is not"

# ---------- apply both, on the A base ----------
fresh; SCHEMA0=$(schema); DATA0=$(data)
fingerprints "$ST/snapshot_v3.sql" > "$W/snap"
[ "$(wc -l < "$W/snap")" = 3 ] && ok "snapshot prints the three fingerprints" || ko "snapshot output: $(cat "$W/snap")"
$P -d "$DB" -At -F '|' -f "$ST/verify_v3.sql" > "$W/v0" 2>&1
if grep -q '|FAIL|' "$W/v0" || grep -q 'ERROR' "$W/v0"; then ok "verify before v3 does not pass (nothing applied yet: $(grep -m1 -oE 'ERROR: .{0,60}|V1[^|]*\|FAIL' "$W/v0"))"
else ko "verify before v3 passed"; fi
expect_ok "ledger applies on a staging-like database (newest = D-08 A)" "$W/apply_$L.sql"
[ "$(q "select count(*) from supabase_migrations.schema_migrations where version = '20261120000000'")" = 1 ] && ok "ledger recorded once" || ko "ledger record"
expect_refusal "ledger twice" "$W/apply_$L.sql" "already recorded"
expect_refusal "rollback business access before it is applied" "$W/rollback_$S.sql" "newest recorded migration is not"
AFTER_L=$(schema); parts > "$W/p1"
expect_ok "business access applies after the ledger" "$W/apply_$S.sql"
expect_refusal "business access twice" "$W/apply_$S.sql" "already recorded"
expect_refusal "rollback the ledger while business access is recorded" "$W/rollback_$L.sql" "newest recorded migration is not"
AFTER_S=$(schema)
[ "$(data | cut -c1-32)" != "" ] && ok "data fingerprint readable"
# the apply files change no data: every table's row count as before, except app_settings (+3 v3 keys)
[ "$(q "select count(*) from public.app_settings where key in ('trial_days','grace_days','launch_at')")" = 3 ] && ok "the three v3 settings added (30, 7, empty)" || ko "v3 settings"
[ "$(q "select value from public.app_settings where key='subscriptions_required'")" = false ] && ok "subscriptions_required still off" || ko "switch changed"
[ "$(q "select value from public.app_settings where key='launch_at'")" = "" ] && ok "no launch date set" || ko "launch date set"

# ---------- verify: V1-V6 all PASS, fingerprints equal the snapshot ----------
$P -d "$DB" -At -F '|' -f "$ST/verify_v3.sql" > "$W/v1" 2>&1
n_pass=$(grep -c '|PASS|' "$W/v1"); n_fail=$(grep -c '|FAIL|' "$W/v1")
[ "$n_fail" = 0 ] && [ "$n_pass" -ge 10 ] && ok "verify after v3: $n_pass checks PASS, none FAIL" || ko "verify after v3: $n_pass PASS, $n_fail FAIL: $(grep '|FAIL|' "$W/v1" | cut -c1-200)"
grep -E '^V[0-9] FINGERPRINT' "$W/v1" | sed -E 's/^V[0-9] FINGERPRINT ([a-z]+)[^|]*\|COMPARE\|/\1|/' | sed -E 's/^(data|settings|visible)\|/\1|/' | sort > "$W/vfp"
sed -E 's/^(data|settings|visible)[^|]*\|/\1|/' "$W/snap" | grep -v '^migrations' | sort > "$W/sfp"
grep -v '^migrations' "$W/snap" > /dev/null
diff -q "$W/vfp" "$W/sfp" >/dev/null && ok "V4/V5 fingerprints after the apply equal the snapshot before it (data, settings, visible to visitors)" || ko "fingerprints differ: snapshot $(tr '\n' ' ' < "$W/sfp") / verify $(tr '\n' ' ' < "$W/vfp")"
[ "$(schema)" = "$AFTER_S" ] && ok "verify changed nothing (ROLLBACK)" || ko "verify changed the database"

# ---------- rollbacks: refuse while v3 holds data, discard variants, exact restore ----------
q "insert into public.business_trials (teacher_id, started_at, ends_at) select id, now(), now() + interval '30 days' from public.teachers limit 1" >/dev/null
expect_refusal "rollback business access while a trial row exists" "$W/rollback_$S.sql" "v3 data would be lost"
q "update public.subscriptions set discount_reason = 'x' where false" >/dev/null
expect_ok "rollback business access, discarding its data (explicit variant)" "$W/rollback_${S}_discard_data.sql"
grep -q 'business_trials_rows_deleted' "$W/out" && ok "the discard variant reports what it deletes" || ko "discard variant printed no counts"
[ "$(schema)" = "$AFTER_L" ] && ok "after rolling business access back: exactly the state after the ledger" || ko "state after business-access rollback differs"
expect_ok "business access applies again" "$W/apply_$S.sql"
expect_ok "rollback business access (no v3 data)" "$W/rollback_$S.sql"
q "insert into public.charges (teacher_id, customer_label, description, amount) select id, 'زبون', 'اختبار', 10 from public.teachers limit 1" >/dev/null
expect_refusal "rollback the ledger while a charge exists" "$W/rollback_$L.sql" "v3 data would be lost"
expect_ok "rollback the ledger, discarding its data (explicit variant)" "$W/rollback_${L}_discard_data.sql"
[ "$(schema)" = "$SCHEMA0" ] && ok "after both rollbacks: exactly the schema before v3" || ko "schema after both rollbacks differs from before v3"
[ "$(data)" = "$DATA0" ] && ok "after both rollbacks: every table's row count as before v3" || ko "data after both rollbacks differs"
expect_ok "ledger applies again after a full rollback" "$W/apply_$L.sql"
[ "$(schema)" = "$AFTER_L" ] && ok "…and the same state as the first time" || { ko "second apply: state differs"; parts > "$W/p2"; diff "$W/p1" "$W/p2" | head -20; }
expect_ok "rollback the ledger (no v3 data)" "$W/rollback_$L.sql"

# ---------- the B base: v3 does not depend on D-08 step B ----------
fresh $BASEB
expect_ok "ledger applies on a base where D-08 B is the newest" "$W/apply_$L.sql"
expect_ok "business access applies there too" "$W/apply_$S.sql"
$P -d "$DB" -At -F '|' -f "$ST/verify_v3.sql" > "$W/vb" 2>&1
[ "$(grep -c '|FAIL|' "$W/vb")" = 0 ] && ok "verify on the B base: no FAIL" || ko "verify on the B base: $(grep '|FAIL|' "$W/vb" | cut -c1-160)"
expect_ok "rollback business access (B base)" "$W/rollback_$S.sql"
expect_ok "rollback the ledger back to D-08 B (B base)" "$W/rollback_$L.sql"
[ "$(q "select max(version) from supabase_migrations.schema_migrations")" = 20261114010000 ] && ok "B base back to D-08 B as newest" || ko "B base newest"

$P -c "drop database if exists $DB" -c "drop database if exists $BASE" -c "drop database if exists $BASEB" >/dev/null 2>&1
rm -rf "$W"
echo "staging v3 files: $pass passed, $fail failed"
[ "$fail" = 0 ]
